import{z as A,x as d,o as E,c as p,q as l,j as s,D as e,d as t,s as i,S as o,b as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"盈余意外","description":"","frontmatter":{"title":"盈余意外","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/earnings-surprise.md","filePath":"quant/earnings-surprise.md","lastUpdated":1791413859000}'),B={name:"quant/earnings-surprise.md"};function h(m,a,u,_,c,P){const r=d("Mermaid");return E(),p("div",null,[a[2]||(a[2]=l('<h1 id="盈余意外" tabindex="-1">盈余意外 <a class="header-anchor" href="#盈余意外" aria-label="Permalink to &quot;盈余意外&quot;">​</a></h1><div class="epigraph"><p>意外是已实现盈余减去当时信息集里的预期；用事后才知道的共识或用错误口径的 EPS，意外就不再是事件，而是数据泄漏。</p><footer>—— 据 Ball and Brown, Journal of Accounting Research, 1968；Livnat and Mendenhall, Journal of Accounting Research, 2006 整理</footer></div><p>上一课<a href="/quant/analyst-revision">分析师预期与修正</a>给出了 as-of 共识。本课把真实盈余接上去，定义意外。真实盈余来自<a href="/quant/three-statements-link">三张表怎么连</a>的利润表，但必须与共识同一口径，并服从<a href="/quant/filing-lag-available-date">财报滞后与可用日期</a>。不重讲共识构造，也不把窗口超额收益提前做成事件研究全文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Ball and Brown 把盈余变化与回报联系起来；后来的标准化意外盈余（SUE）把「变化」换成相对预期的差。预期可以是分析师共识，也可以是时间序列模型（季节随机游走）。Livnat–Mendenhall 表明两种意外并非同一排序：分析师意外与季节差分意外相关有限，后续漂移不同。缺口是锁死减数：在公告日可用的那一个预期，而不是样本期内最好看的那一个。</p><p>口径冲突是第二层缺口。共识常是摊薄后经营 EPS；报表公布的是 GAAP 净利润。用 GAAP 减经营共识，意外里全是一次性项目与稀释差，不是「市场没料到的经营」。</p><p><span class="marginnote">时点可用（PIT，point-in-time）就是只使用公告日当天之前已经公开、且此后未被修订的数据版本。初学者常直接从今天的数据库取「当时的共识」，但库里可能已被事后补改，一取就把未来信息漏进了减数。</span></p><h3 id="意外不是盈利水平" tabindex="-1">意外不是盈利水平 <a class="header-anchor" href="#意外不是盈利水平" aria-label="Permalink to &quot;意外不是盈利水平&quot;">​</a></h3><p>高盈利可以零意外，低盈利可以大正意外。质量与盈利因子交易水平或持续性；意外交易<strong>相对于当时预期的差</strong>。把 PEAD 做成「买盈利高的」，是回到上一课程的盈利因子，不是本课。</p><p><span class="marginnote">标准化常用股价或预期的标准差。除数接近零时（微利、共识接近零）SUE 爆炸，必须截尾，否则排序被分母劫持。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(SUE_t = (X_t - \\mathbb{E}[X_t\\mid \\mathcal F_{t-}]) / s_t\\)。\\(X_t\\) 与 \\(\\mathbb{E}\\) 必须同为摊薄 EPS 或同为净利润；\\(\\mathcal F_{t-}\\) 是公告前信息集，共识取上一课的 PIT 切片，时间序列预期只用公告前已实现的季报。\\(s_t\\) 用历史意外波动或价格。可用日期：真实 \\(X_t\\) 在公告日才进入，不能用后来 restated 的 EPS 去减当时共识。</p><p>季节随机游走 \\(\\mathbb{E}[X_t]=X_{t-4}\\) 不需要分析师库，但小公司覆盖不足时更常用；它不是 PIT 的替代，历史 \\(X_{t-4}\\) 仍要当时可用版本。</p><p><span class="marginnote">数字实例：实际 EPS 0.52 元、公告前共识 0.50 元，过去八季意外标准差 0.02，则 SUE = (0.52 − 0.50)/0.02 = 1。若除数误取 0.004，同一个意外会变成 SUE = 5，直接顶到排序最前端——这正是必须截尾的原因。</span></p>',14)),(E(),s(o,null,{default:e(()=>[i(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXP%5B%22PIT%20%E9%A2%84%E6%9C%9F%22%5D%20--%3E%20DIFF%5B%22%E5%B7%B2%E5%AE%9E%E7%8E%B0%E5%87%8F%E9%A2%84%E6%9C%9F%22%5D%0A%20%20ACT%5B%22%E5%85%AC%E5%91%8A%E6%97%A5%E7%9C%9F%E5%AE%9E%E7%9B%88%E4%BD%99%22%5D%20--%3E%20DIFF%0A%20%20DIFF%20--%3E%20SUE%5B%22%E6%A0%87%E5%87%86%E5%8C%96%E6%84%8F%E5%A4%96%22%5D%0A%20%20SUE%20--%3E%20WIN%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%85%AC%E5%91%8A%E7%AA%97%E5%8F%A3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"正意外带来正的公告回报，并常伴随事后漂移（PEAD）。机制解释有延迟反应与风险补偿两派，本课不裁决。回测要先保证意外本身干净：restated EPS、错误财期、盘后公告记错交易日，都会制造假漂移。后课窗口研究把意外当条件变量；本课只交付这个变量。与应计的关系：高应计公司更容易出现负的后续意外，质量与惊喜会共线，组合时要声明是否正交。",-1)),(E(),s(o,null,{default:e(()=>[i(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%85%AC%E5%91%8A%E6%97%A5%E7%9C%9F%E5%AE%9E%E5%80%BC%22%5D%20--%3E%20B%7B%22%E4%B8%8E%E5%85%B1%E8%AF%86%E5%90%8C%E5%8F%A3%E5%BE%84%3F%22%7D%0A%20%20B%20--%20%22%E5%90%A6%3A%20GAAP%20%E5%87%8F%E7%BB%8F%E8%90%A5%E5%85%B1%E8%AF%86%22%20--%3E%20C%5B%22%E4%B8%80%E6%AC%A1%E6%80%A7%E9%A1%B9%E7%9B%AE%E6%B7%B7%E5%85%A5%E6%84%8F%E5%A4%96%22%5D%0A%20%20B%20--%20%22%E6%98%AF%22%20--%3E%20D%7B%22%E7%94%A8%E7%9A%84%E6%98%AF%E5%BD%93%E6%97%B6%E7%89%88%E6%9C%AC%3F%22%7D%0A%20%20D%20--%20%22%E5%90%A6%3A%20restated%20%E6%88%96%E4%BA%8B%E5%90%8E%E5%85%B1%E8%AF%86%22%20--%3E%20E%5B%22%E6%83%8A%E5%96%9C%E8%A2%AB%E5%8E%8B%E5%B9%B3%E6%88%96%E8%99%9A%E5%A2%9E%22%5D%0A%20%20D%20--%20%22%E6%98%AF%22%20--%3E%20F%5B%22%E5%B9%B2%E5%87%80%E7%9A%84%20SUE%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">财报常在盘后发布：若把盘后公告记成当天这个交易日，回测会按公告前的价格「买进」，等于用了未公开信息，凭空做出一段公告日回报。正确做法是按发布时刻把它归到下一个可交易时段。</span></p><p><span class="marginnote">分析师惊喜与财报质量课的「一次性项目」重叠。若共识已排除某项而 GAAP 未排除，意外会系统性等于该项。先对齐口径，再谈 alpha。</span></p><p>真实 EPS 取公告日当日版本，与共识的摊薄/扣非/是否含一次性同一行对齐。标准化除数用公告前股价或过去八季意外的标准差，并对 SUE 分位前截尾。没有分析师覆盖的公司改用 \\(X_t-X_{t-4}\\)，但 \\(X_{t-4}\\) 仍是当时可用版本。不要把公告后才修订的共识插回减数——那会把惊喜压向零，制造「市场早已知道」的假象。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不估计完整 PEAD 策略，不写高频「抢跑」。窗口如何定义、隔夜如何归属，下一课<a href="/quant/earnings-announcement-window">财报公告窗口</a>。后课默认：意外 = 公告日真实值 − 公告前 PIT 预期，口径已锁，极端值已截尾。</p><p>后课窗口把 SUE 当条件分组变量，不再改它的定义。本课锁死：减数是公告前 PIT 预期，被减数是公告日真实值，除数在公告前已知，极端值已截尾。分析师 SUE 与季节 SUE 若都算，当作两个信号，不要平均成一个还称为「意外」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>意外是相对当时预期的差，不是盈利水平。</li><li>分析师 SUE 与季节差分 SUE 不是同一信号。</li><li>真实值与预期必须同口径，且真实值走公告日 PIT。</li><li>标准化除数过小要截尾。</li><li>后课窗口把本课的意外当条件。</li><li>出处：Ball and Brown (1968)；Livnat and Mendenhall (2006)；IBES 与季节随机游走惯例。</li></ul>',8))])}const F=A(B,[["render",h]]);export{f as __pageData,F as default};
